   [175]={next_id=176, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在我眼里，只有妈妈有时候分不清我是谁，她常常对着我喊出姐姐的名字。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [176]={next_id=177, abreast_id={}, pType =1, cg_type =5, dialog=0, msg="转场效果:arts/storyPrefab/prefab/common/prefab/FlashBack.prefab", msg_color="", msg_size=0, talker="", audio="", img="", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="arts/storyPrefab/prefab/common/prefab/FlashBack.prefab", runTalkTime =758, destoryTime =1516, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [177]={next_id=178, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她显然也知道你在想什么。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [178]={next_id=179, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="听起来很不可思议对吧……从那时开始，我彻底地接受了自己新的身份，妈妈常常对我说，我是她失而复得的星星，所以要好好地生活，这样她和爸爸的生命才不会一片黑暗。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [179]={next_id=180, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我试过去压抑自己的仇恨，也很努力地在伪装成一个正常人。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [180]={next_id=181, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我逼迫自己忘记过往，想要像妈妈期待的那样、平安却普通地活着。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [181]={next_id=182, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……如果你真的可以那样一直下去，一定也很好。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [182]={next_id=183, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维瑟内特“嗯”了一声，带着浓浓的鼻音。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [183]={next_id=184, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如果没有发现因斐诺的遗蠹仍旧活跃在这个世界上的话，那大概是可以如愿的。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [184]={next_id=185, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那之后我借口对历史感兴趣，爸爸马上为我买回了全套的历史书，他还被妈妈骂了一顿，说一下子买那么深奥的书我怎么可能会看懂。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [185]={next_id=186, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她由衷地笑出了声。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [186]={next_id=187, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="根据自己的一些记忆，我大概判断出了从以前到现在的时间……", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4533", 0, 0, 88.5, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [187]={next_id=188, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维瑟内特忽然停顿了，她慢慢地松开你，挪动身体与你拉开了一个手掌的距离。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
