   [189]={next_id=190, abreast_id={}, pType =1, cg_type =5, dialog=0, msg="转场效果:arts/storyPrefab/prefab/common/prefab/FlashBack.prefab", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_501.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="arts/storyPrefab/prefab/common/prefab/FlashBack.prefab", runTalkTime =758, destoryTime =1516, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [190]={next_id=191, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她用力地呼吸，声音都在颤抖。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="1006", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [191]={next_id=192, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……我出生在普瑞斯城的一个小贵族家里，有一个姐姐……这件事我对你说过。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [192]={next_id=193, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="令姐姐出事的那场意外用现在的话来说，叫做虚粒子污染，原因是坎贝尔家族在郊外捕捉修格尔。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [193]={next_id=194, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在那之后过了两年，坎贝尔家族的尊贵客人来到了我家，说我是被“神明”选中的孩子。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [194]={next_id=195, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她情不自禁避开了你的视线。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [195]={next_id=196, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="于是我被带去了普瑞斯城的地下，在那儿，我见到了维里塔，她给了我一个编号。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [196]={next_id=197, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="呵呵……", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [197]={next_id=198, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维瑟内特攥紧拳头，喉咙中的声音不知道是哭还是笑。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [198]={next_id=199, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我只见过她这么一次，但我从未忘记她……那副丑陋又傲慢的面孔，每当我想起来就会忍不住作呕。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
