   [201]={next_id=202, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我，还有很多人，我们的身体里被注射了奇怪的药剂，很多的人都死去了，只有我一直活着。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [202]={next_id=203, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虽然我那会儿还很小，但也能听懂她们说什么，我的试验数据被记录并小心地保存，我脸上的“胎记”就是那个时候出现的。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
