   [204]={next_id=205, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="由于克里安卡、以及维瑟内特的某些表现，你曾有过类似的猜测，只是不敢完全确信。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [205]={next_id=206, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="维瑟内特同样意识到了你的沉默，她很快地抬头又迅速低下头，有些破罐子破摔般地继续诉说。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [206]={next_id=207, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那些人的狂热没有维持太久，在灾难发生后，所有的研究人员为了活命四散逃窜，把我们这些试验体留在了里面。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
