   [208]={next_id=209, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那儿本来就是坎贝尔公爵举全国之力建造的基因科学实验室，还关了许多危险的生物。", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [209]={next_id=210, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="忘了哪天了，我们被一只修格尔逼到了绝路，我眼睁睁看着一些同伴死去，突然就触发了星源力量……我杀掉了它，然后发现另一些同伴不见了，我也不知道她们是不是死了……", msg_color="", msg_size=0, talker="维瑟内特", audio="", img="arts/ui/bg/story/cg/cg_ACT307_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
